diff.patch:
diff --git a/design-system/wireframes/onboarding-request-flow.html b/design-system/wireframes/onboarding-request-flow.html
new file mode 100644
index 0000000..7ef54e2
--- /dev/null
+++ b/design-system/wireframes/onboarding-request-flow.html
@@ -0,0 +1,1184 @@
+<!-- @dsCard group="Onboarding Requests" viewport="1180x1480" name="Public account request flow" subtitle="/get-started email verification, verified request states, acknowledgement, and staff onboarding branch" -->
+<!-- @startingPoint section="Onboarding Requests" subtitle="Public requester asks Memba staff to create a group space only after verifying email control" viewport="1180x1480" -->
+<!doctype html>
+<html lang="en" data-theme="light">
+<head>
+  <meta charset="utf-8">
+  <title>Public account request flow · Memba</title>
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap">
+
+  <!-- daisyUI component CSS, prebuilt — renders the app's daisyUI components with no build step. -->
+  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/daisyui@5">
+
+  <style>
+    /* Memba raw tokens (mirror of web/assets/css/app.css @theme). */
+    :root {
+      --color-sage-50:#eef1e6;
+      --color-sage-100:#dde3cf;
+      --color-sage-200:#bccaa6;
+      --color-sage-300:#98ab80;
+      --color-sage-400:#6f8760;
+      --color-sage-500:#5a7050;
+      --color-sage-600:#475a40;
+      --color-sage-700:#36462f;
+      --color-sage-800:#232e1e;
+
+      --color-cream:#f6f5ea;
+      --color-paper:#fffef9;
+      --color-apricot:#d2925a;
+      --color-apricot-soft:#f6e8d6;
+      --color-apricot-deep:#925f2e;
+
+      --color-ink:#25291d;
+      --color-ink-2:#555a47;
+      --color-ink-3:#878b76;
+
+      --color-line:#e8e6d4;
+      --color-line-strong:#d9d6bf;
+      --color-success:#5f7a4f;
+      --color-warning:#a8772e;
+      --color-error:#a8503a;
+      --color-info:#4f6b78;
+      --color-success-soft:#e9eedd;
+      --color-warning-soft:#f3ecd8;
+      --color-error-soft:#f1ddd3;
+      --color-info-soft:#e3e9ec;
+
+      --font-sans:"Figtree",ui-sans-serif,system-ui,sans-serif;
+      --font-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
+    }
+
+    /* daisyUI "light" theme — copied from web/assets/css/app.css. */
+    :root {
+      color-scheme:light;
+      --color-base-100:#fffef9;
+      --color-base-200:#f6f5ea;
+      --color-base-300:#e8e6d4;
+      --color-base-content:#25291d;
+      --color-primary:#5a7050;
+      --color-primary-content:#f6f5ea;
+      --color-secondary:#555a47;
+      --color-secondary-content:#f6f5ea;
+      --color-accent:#d2925a;
+      --color-accent-content:#25291d;
+      --color-neutral:#25291d;
+      --color-neutral-content:#f6f5ea;
+      --color-info:#4f6b78;
+      --color-info-content:#f6f5ea;
+      --color-success:#5f7a4f;
+      --color-success-content:#f6f5ea;
+      --color-warning:#a8772e;
+      --color-warning-content:#f6f5ea;
+      --color-error:#a8503a;
+      --color-error-content:#f6f5ea;
+      --radius-selector:0.375rem;
+      --radius-field:0.375rem;
+      --radius-box:0.75rem;
+      --size-selector:0.25rem;
+      --size-field:0.25rem;
+      --border:1px;
+      --depth:0;
+      --noise:0;
+    }
+
+    * { box-sizing:border-box; }
+    html, body { margin:0; }
+    body {
+      min-height:100vh;
+      background:var(--color-base-200);
+      color:var(--color-base-content);
+      font-family:var(--font-sans);
+      -webkit-font-smoothing:antialiased;
+      text-rendering:optimizeLegibility;
+    }
+    a { color:inherit; text-decoration:none; }
+    h1, h2, h3, p { margin:0; }
+    code { font-family:var(--font-mono); }
+
+    .preview-shell {
+      display:grid;
+      gap:28px;
+      padding:28px;
+    }
+    .preview-title {
+      align-items:flex-end;
+      display:flex;
+      gap:18px;
+      justify-content:space-between;
+      margin:0 auto;
+      max-width:1120px;
+      width:100%;
+    }
+    .preview-title__eyebrow {
+      color:var(--color-ink-3);
+      font-size:12px;
+      font-weight:700;
+      letter-spacing:0.18em;
+      text-transform:uppercase;
+    }
+    .preview-title h1 {
+      color:var(--color-ink);
+      font-size:34px;
+      font-weight:700;
+      letter-spacing:-0.035em;
+      line-height:1.05;
+      margin-top:5px;
+    }
+    .preview-title p {
+      color:var(--color-ink-2);
+      font-size:14px;
+      line-height:1.45;
+      margin-top:8px;
+      max-width:66ch;
+    }
+    .variant-label {
+      border:1px solid var(--color-line-strong);
+      border-radius:999px;
+      color:var(--color-ink-2);
+      font-family:var(--font-mono);
+      font-size:11px;
+      padding:7px 10px;
+      white-space:nowrap;
+    }
+
+    .flow-strip {
+      background:var(--color-paper);
+      border:1px solid var(--color-line-strong);
+      border-radius:20px;
+      display:grid;
+      gap:10px;
+      grid-template-columns:repeat(5, minmax(0, 1fr));
+      margin:0 auto;
+      max-width:1120px;
+      padding:12px;
+      width:100%;
+    }
+    .flow-step {
+      background:var(--color-base-200);
+      border:1px solid var(--color-line);
+      border-radius:16px;
+      display:grid;
+      gap:4px;
+      min-height:94px;
+      padding:13px;
+    }
+    .flow-step strong {
+      color:var(--color-ink);
+      font-size:13px;
+      line-height:1.25;
+    }
+    .flow-step span {
+      color:var(--color-ink-2);
+      font-size:12px;
+      line-height:1.35;
+    }
+    .flow-step code {
+      color:var(--color-sage-700);
+      font-size:10px;
+      letter-spacing:0.02em;
+    }
+
+    .surface-stack {
+      display:grid;
+      gap:24px;
+      margin:0 auto;
+      max-width:1120px;
+      width:100%;
+    }
+    .surface-grid {
+      display:grid;
+      gap:24px;
+      grid-template-columns:minmax(0, 1fr) minmax(0, 1fr);
+      width:100%;
+    }
+    .surface-card {
+      background:var(--color-paper);
+      border:1px solid var(--color-line-strong);
+      border-radius:24px;
+      box-shadow:0 16px 40px rgba(37,41,29,0.08);
+      min-width:0;
+      overflow:hidden;
+    }
+    .surface-card--wide {
+      grid-column:1 / -1;
+    }
+    .surface-caption {
+      align-items:center;
+      background:var(--color-sage-800);
+      color:var(--color-cream);
+      display:flex;
+      gap:14px;
+      justify-content:space-between;
+      padding:12px 16px;
+    }
+    .surface-caption strong {
+      font-size:13px;
+      font-weight:700;
+      letter-spacing:0.01em;
+    }
+    .surface-caption span {
+      color:rgba(246,245,234,0.68);
+      font-family:var(--font-mono);
+      font-size:10px;
+    }
+
+    .app-chrome {
+      background:var(--color-base-200);
+      min-height:760px;
+    }
+    .app-chrome--compact {
+      min-height:650px;
+    }
+    .app-header {
+      background:rgba(255,254,249,0.88);
+      border-bottom:1px solid var(--color-line);
+      padding:16px 22px;
+    }
+    .app-header__inner {
+      align-items:center;
+      display:flex;
+      gap:18px;
+      justify-content:space-between;
+      margin:0 auto;
+      max-width:1180px;
+    }
+    .brand-link {
+      align-items:center;
+      display:inline-flex;
+      gap:10px;
+      transition:opacity 160ms ease;
+      width:max-content;
+    }
+    .brand-link:hover { opacity:0.82; }
+    .sprig {
+      color:var(--color-sage-600);
+      display:block;
+      height:28px;
+      width:28px;
+    }
+    .wordmark {
+      color:var(--color-ink);
+      font-size:24px;
+      font-weight:650;
+      letter-spacing:-0.035em;
+      line-height:1;
+      text-transform:lowercase;
+    }
+    .public-nav {
+      align-items:center;
+      display:flex;
+      flex-wrap:wrap;
+      gap:10px;
+      color:var(--color-ink-2);
+      font-size:13px;
+      font-weight:600;
+    }
+    .public-nav a,
+    .public-nav span {
+      border-radius:999px;
+      display:inline-flex;
+      padding:8px 11px;
+    }
+    .public-nav .nav-bordered {
+      background:var(--color-paper);
+      border:1px solid var(--color-line-strong);
+      color:var(--color-ink);
+      padding:8px 14px;
+    }
+    .public-nav .nav-primary {
+      background:var(--color-sage-600);
+      border:1px solid var(--color-sage-600);
+      color:var(--color-cream);
+      font-weight:700;
+      padding:8px 14px;
+    }
+    .app-main {
+      padding:54px 26px 68px;
+    }
+    .app-main__inner {
+      display:grid;
+      gap:16px;
+      margin:0 auto;
+      max-width:672px;
+    }
+    .app-main__inner--wide {
+      max-width:920px;
+    }
+
+    .get-started-section,
+    .auth-section,
+    .staff-section {
+      display:grid;
+      gap:32px;
+    }
+    .hero-copy {
+      display:grid;
+      gap:16px;
+    }
+    .eyebrow {
+      color:var(--color-sage-600);
+      font-size:13px;
+      font-weight:700;
+      letter-spacing:0.2em;
+      line-height:1.2;
+      text-transform:uppercase;
+    }
+    .hero-copy h2,
+    .hero-copy h3 {
+      color:var(--color-ink);
+      font-size:43px;
+      font-weight:650;
+      letter-spacing:-0.045em;
+      line-height:1.02;
+    }
+    .hero-copy p {
+      color:var(--color-ink-2);
+      font-size:18px;
+      line-height:1.78;
+    }
+
+    .request-flow {
+      display:grid;
+      gap:28px;
+      grid-template-columns:minmax(0, 0.92fr) minmax(0, 1.08fr);
+      align-items:start;
+    }
+    .info-card,
+    .request-card,
+    .notice-card {
+      background:var(--color-paper);
+      border:1px solid var(--color-line);
+      border-radius:24px;
+      box-shadow:0 1px 2px rgba(37,41,29,0.05);
+      padding:24px;
+    }
+    .info-card h3,
+    .notice-card h3 {
+      color:var(--color-ink);
+      font-size:24px;
+      font-weight:650;
+      letter-spacing:-0.025em;
+      line-height:1.15;
+    }
+    .info-card p,
+    .notice-card p {
+      color:var(--color-ink-2);
+      font-size:15px;
+      line-height:1.65;
+      margin-top:13px;
+    }
+    .bullet-list {
+      display:grid;
+      gap:12px;
+      list-style:none;
+      margin:22px 0 0;
+      padding:0;
+    }
+    .bullet-list li {
+      color:var(--color-ink-2);
+      display:flex;
+      font-size:14px;
+      gap:12px;
+      line-height:1.5;
+    }
+    .bullet-dot {
+      background:var(--color-sage-600);
+      border-radius:999px;
+      flex:none;
+      height:8px;
+      margin-top:7px;
+      width:8px;
+    }
+
+    .callout {
+      background:var(--color-sage-50);
+      border:1px solid var(--color-sage-200);
+      border-radius:16px;
+      padding:15px;
+    }
+    .callout strong {
+      color:var(--color-sage-800);
+      display:block;
+      font-size:14px;
+      font-weight:700;
+      line-height:1.35;
+    }
+    .callout p {
+      color:var(--color-ink-2);
+      font-size:14px;
+      line-height:1.55;
+      margin-top:8px;
+    }
+    .callout dl {
+      display:grid;
+      gap:12px;
+      grid-template-columns:repeat(2, minmax(0, 1fr));
+      margin:14px 0 0;
+    }
+    .callout dt {
+      color:var(--color-ink-3);
+      font-size:12px;
+      font-weight:700;
+      line-height:1.35;
+    }
+    .callout dd {
+      color:var(--color-ink);
+      font-size:14px;
+      line-height:1.35;
+      margin:4px 0 0;
+    }
+
+    .form-stack {
+      display:grid;
+      gap:18px;
+    }
+    .field-wrap {
+      display:grid;
+      gap:7px;
+    }
+    .label {
+      color:var(--color-ink);
+      font-size:14px;
+      font-weight:500;
+      line-height:1.25;
+    }
+    .input,
+    .textarea {
+      width:100%;
+    }
+    .textarea {
+      min-height:118px;
+    }
+    .button-row {
+      align-items:center;
+      display:flex;
+      flex-wrap:wrap;
+      gap:12px;
+      margin-top:4px;
+    }
+    .btn-primary {
+      background:var(--color-primary);
+      border-color:var(--color-primary);
+      color:var(--color-primary-content);
+    }
+    .scope-note {
+      color:var(--color-ink-3);
+      font-size:14px;
+      line-height:1.5;
+      margin-top:14px;
+    }
+    .field-error {
+      align-items:center;
+      color:var(--color-error);
+      display:flex;
+      font-size:13px;
+      gap:8px;
+      line-height:1.35;
+      margin-top:1px;
+    }
+    .error-dot {
+      background:var(--color-error);
+      border-radius:999px;
+      display:inline-block;
+      flex:none;
+      height:7px;
+      width:7px;
+    }
+
+    .progress-card {
+      background:var(--color-paper);
+      border:1px solid var(--color-line);
+      border-radius:24px;
+      box-shadow:0 1px 2px rgba(37,41,29,0.05);
+      padding:24px;
+    }
+    .progress-panel {
+      background:rgba(238,241,230,0.72);
+      border:1px solid var(--color-sage-200);
+      border-radius:16px;
+      padding:16px;
+    }
+    .progress-panel strong {
+      color:var(--color-sage-700);
+      display:block;
+      font-size:12px;
+      font-weight:700;
+      letter-spacing:0.18em;
+      text-transform:uppercase;
+    }
+    .progress-panel p {
+      color:var(--color-ink);
+      font-size:16px;
+      line-height:1.55;
+      margin-top:9px;
+    }
+    .progress-states {
+      display:grid;
+      gap:10px;
+      margin-top:18px;
+    }
+    .progress-state {
+      align-items:flex-start;
+      border:1px solid var(--color-line);
+      border-radius:14px;
+      display:flex;
+      gap:10px;
+      padding:11px 12px;
+    }
+    .progress-state .badge {
+      flex:none;
+      margin-top:1px;
+    }
+    .progress-state span {
+      color:var(--color-ink-2);
+      display:block;
+      font-size:13px;
+      line-height:1.45;
+    }
+    .progress-card > p {
+      color:var(--color-ink-3);
+      font-size:14px;
+      line-height:1.55;
+      margin-top:18px;
+    }
+
+    .ack-card {
+      background:var(--color-sage-50);
+      border:1px solid var(--color-sage-200);
+      border-radius:24px;
+      box-shadow:0 1px 2px rgba(37,41,29,0.05);
+      padding:28px;
+    }
+    .ack-card .eyebrow {
+      color:var(--color-sage-700);
+    }
+    .ack-card h3 {
+      color:var(--color-ink);
+      font-size:26px;
+      font-weight:650;
+      letter-spacing:-0.03em;
+      margin-top:12px;
+    }
+    .ack-card p {
+      color:var(--color-ink-2);
+      font-size:16px;
+      line-height:1.65;
+      margin-top:15px;
